CREATE TABLE IF NOT EXISTS games (
  id VARCHAR(255) PRIMARY KEY,
  name VARCHAR(255) NOT NULL,
  console VARCHAR(100),
  genre VARCHAR(100) DEFAULT '',
  completion_level VARCHAR(50) DEFAULT 'jogado',
  rating NUMERIC(4, 1) DEFAULT 0,
  image_url TEXT DEFAULT '',
  is_favorite BOOLEAN DEFAULT FALSE,
  acquired_date TEXT DEFAULT '',
  acquired_source TEXT DEFAULT '',
  played_period TEXT DEFAULT '',
  finish_date TEXT DEFAULT '',
  hours_played TEXT DEFAULT '',
  media_type TEXT DEFAULT '',
  difficulty VARCHAR(100) DEFAULT 'Normal',
  personal_notes TEXT DEFAULT '',
  achievements JSONB DEFAULT '[]'::jsonb,
  updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

